<template><p v-if="error" class="alert">{{ error }}</p><div class="feature-grid"><article v-for="feature in features" :key="feature.key" class="panel feature-card"><div class="panel-head"><div><p class="eyebrow">{{ feature.key }}</p><h2>{{ feature.name }}</h2></div><span :class="['pill', feature.status.toLowerCase()]">{{ feature.status }}</span></div><p>{{ feature.description }}</p><label>发布状态<select v-model="feature.status"><option>ACTIVE</option><option>BETA</option><option>PAUSED</option></select></label><label>维护提示<textarea v-model="feature.maintenanceMessage" rows="3" placeholder="PAUSED 时展示"></textarea></label><label>平台（逗号分隔）<input :value="feature.platforms.join(', ')" @input="feature.platforms = $event.target.value.split(',').map(v => v.trim()).filter(Boolean)" /></label><div class="card-foot"><small>授权 {{ feature.activeGrants }} · 权益 {{ feature.activeEntitlements }} · v{{ feature.version }}</small><button class="primary compact" @click="save(feature)">保存发布配置</button></div></article></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { readableError, request, requireReauth } from '../api';
const features = ref([]); const error = ref('');
async function load() { try { features.value = await request('/features'); } catch (caught) { error.value = readableError(caught); } }
async function save(feature) { const reason = prompt('请填写本次发布变更原因：'); if (!reason) return; try { await requireReauth(); await request(`/features/${feature.key}`, { method: 'PATCH', body: { status: feature.status, platforms: feature.platforms, maintenanceMessage: feature.maintenanceMessage, runtimeConfig: feature.runtimeConfig, version: feature.version, reason } }); await load(); } catch (caught) { error.value = readableError(caught); } }
onMounted(load);
</script>
